import{_ as e,o as t,c as n,a3 as o}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Banking and money transfers","description":"What a bank asks for when you open an account, how transfers work in Qatar, where to complain about a bank, and how to protect yourself from fraud.","frontmatter":{"title":"Banking and money transfers","description":"What a bank asks for when you open an account, how transfers work in Qatar, where to complain about a bank, and how to protect yourself from fraud.","lastChecked":"2026-10","sourceCount":7},"headers":[],"relativePath":"guide/banking-and-money.md","filePath":"guide/banking-and-money.md"}'),r={name:"guide/banking-and-money.md"};function s(f,a,i,l,c,h){return t(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="banking-and-money-transfers" tabindex="-1">Banking and money transfers <a class="header-anchor" href="#banking-and-money-transfers" aria-label="Permalink to &quot;Banking and money transfers&quot;">​</a></h1><p>Qatar Central Bank (QCB) supervises the banks operating in Qatar,<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> and it has a department that handles customer complaints. This page covers the basics for anyone who lives in Qatar and uses a bank here.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><h2 id="opening-a-bank-account" tabindex="-1">Opening a bank account <a class="header-anchor" href="#opening-a-bank-account" aria-label="Permalink to &quot;Opening a bank account&quot;">​</a></h2><p>QCB&#39;s instructions to banks list what goes into a personal account file. They apply to residents and non-residents, but this edition is from September 2013, so ask your bank for its current checklist before you go.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><p>What you need to give the bank:<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></p><ul><li>A full copy of your valid passport or identification card.<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3]</a></sup></li><li>A personal photograph or fingerprints, as the instructions require.<sup class="footnote-ref"><a href="#fn3" id="fnref3:3">[3]</a></sup></li><li>Your full name as shown on your passport or ID, your nationality, and your place and date of birth.<sup class="footnote-ref"><a href="#fn3" id="fnref3:4">[3]</a></sup></li><li>Your profession, workplace, place of residence and postal address.<sup class="footnote-ref"><a href="#fn3" id="fnref3:5">[3]</a></sup></li><li>If you live in Qatar, the name and address of your sponsor or employer.<sup class="footnote-ref"><a href="#fn3" id="fnref3:6">[3]</a></sup></li><li>Your signature or fingerprint.<sup class="footnote-ref"><a href="#fn3" id="fnref3:7">[3]</a></sup></li></ul><p>Things to know before you apply:<sup class="footnote-ref"><a href="#fn3" id="fnref3:8">[3]</a></sup></p><ul><li>You normally have only one main account with a bank, though sub-accounts can sit under it.<sup class="footnote-ref"><a href="#fn3" id="fnref3:9">[3]</a></sup></li><li>Before opening a current account, the bank must check you against the rules on returned cheques.<sup class="footnote-ref"><a href="#fn3" id="fnref3:10">[3]</a></sup></li><li>Cheques cannot be used to draw money from a savings account.<sup class="footnote-ref"><a href="#fn3" id="fnref3:11">[3]</a></sup></li></ul><h2 id="getting-your-salary" tabindex="-1">Getting your salary <a class="header-anchor" href="#getting-your-salary" aria-label="Permalink to &quot;Getting your salary&quot;">​</a></h2><p>The Wage Protection System is run with the Ministry of Labour to manage and verify wage payments from employers to employees. Its purpose and your rights under it are covered in <a href="./work-and-labour-rights">Work and labour rights</a>.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></p><h2 id="sending-money-inside-qatar" tabindex="-1">Sending money inside Qatar <a class="header-anchor" href="#sending-money-inside-qatar" aria-label="Permalink to &quot;Sending money inside Qatar&quot;">​</a></h2><ul><li>Fawran is the instant payment system, launched in 2024. It moves money between bank accounts at any time of day, and you can pay someone using their mobile number, alias or IBAN.<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4]</a></sup></li><li>Participating banks listed by QCB include QNB, Commercial Bank, QIB, Ahli Bank, Dukhan Bank, Doha Bank, QIIB, Al Rayan Bank, HSBC and Standard Chartered.<sup class="footnote-ref"><a href="#fn4" id="fnref4:2">[4]</a></sup></li><li>Tahweel is the older system for transfers between bank accounts at banks in Qatar.<sup class="footnote-ref"><a href="#fn4" id="fnref4:3">[4]</a></sup></li><li>Qatar Mobile Payment (QMP) handles instant transfers between e-wallets with payment service providers in Qatar.<sup class="footnote-ref"><a href="#fn4" id="fnref4:4">[4]</a></sup></li></ul><h2 id="exchange-houses" tabindex="-1">Exchange houses <a class="header-anchor" href="#exchange-houses" aria-label="Permalink to &quot;Exchange houses&quot;">​</a></h2><p>QCB&#39;s instructions define an exchange house as a licensed company that exchanges money and does not take deposits.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup> QCB&#39;s Licensing Section handles the licences of the institutions it supervises, including renewals and cancellations.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></p><h2 id="complaining-about-a-bank" tabindex="-1">Complaining about a bank <a class="header-anchor" href="#complaining-about-a-bank" aria-label="Permalink to &quot;Complaining about a bank&quot;">​</a></h2><p>QCB&#39;s Customer Protection Department receives customer complaints and says it deals with them fairly and impartially.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></p><ul><li>Complaints line for financial institutions: 8000700.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li>Complaints line for insurance companies: 44456377.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup></li><li>Email: <a href="mailto:cp@qcb.gov.qa" target="_blank" rel="noreferrer">cp@qcb.gov.qa</a>.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup></li><li>In person: Qatar Central Bank, West Bay, 8:00 AM to 1:00 PM.<sup class="footnote-ref"><a href="#fn2" id="fnref2:5">[2]</a></sup></li></ul><h2 id="avoiding-fraud" tabindex="-1">Avoiding fraud <a class="header-anchor" href="#avoiding-fraud" aria-label="Permalink to &quot;Avoiding fraud&quot;">​</a></h2><p>QCB&#39;s Stay Aware campaign says scammers may pretend to be your bank, and that the main channels are phone calls, social media, email, SMS and links.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></p><ul><li>Never share your card details or one-time password (OTP).<sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7]</a></sup></li><li>Do not answer unknown international calls, and be careful with unknown local callers.<sup class="footnote-ref"><a href="#fn7" id="fnref7:2">[7]</a></sup></li><li>Avoid opening links in SMS messages, and check who the sender really is.<sup class="footnote-ref"><a href="#fn7" id="fnref7:3">[7]</a></sup></li><li>If a call seems fraudulent, contact the organisation directly using its official channels.<sup class="footnote-ref"><a href="#fn7" id="fnref7:4">[7]</a></sup></li><li>If your card is lost or stolen, block it straight away through your bank&#39;s call centre or app.<sup class="footnote-ref"><a href="#fn7" id="fnref7:5">[7]</a></sup></li></ul><p>To report financial cybercrime, call the hotline on 66815757, use the Metrash2 app, or email <a href="mailto:cccc@moi.gov.qa" target="_blank" rel="noreferrer">cccc@moi.gov.qa</a>.<sup class="footnote-ref"><a href="#fn7" id="fnref7:6">[7]</a></sup></p><p>See also: <a href="./work-and-labour-rights">Work and labour rights</a>, <a href="./metrash">Metrash</a>, <a href="./cost-of-living">Cost of living basics</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Qatar Central Bank, <a href="https://www.qcb.gov.qa/en/Supervision/pages/bankingsupervisiondepartmentsectors.aspx" target="_blank" rel="noreferrer">Banking Supervision Department</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Qatar Central Bank, <a href="https://www.qcb.gov.qa/en/pages/customer-protection-department.aspx" target="_blank" rel="noreferrer">Customer Protection Department</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:5" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Qatar Central Bank, <a href="https://www.qcb.gov.qa/Documents/BankInstructions/EN/07-04.pdf" target="_blank" rel="noreferrer">Instructions to Banks, Part VII, Chapter Four: Relation with Customers, September 2013</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:9" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:10" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:11" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Qatar Central Bank, <a href="https://www.qcb.gov.qa/en/Pages/Retail-payment-systems.aspx" target="_blank" rel="noreferrer">Retail Payment Systems</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Qatar Central Bank, <a href="https://www.qcb.gov.qa/Documents/BankInstructions/EN/def.pdf" target="_blank" rel="noreferrer">Instructions to Banks: Definitions, September 2013</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Qatar Central Bank, <a href="https://www.qcb.gov.qa/en/Supervision/pages/licensingdepartment.aspx" target="_blank" rel="noreferrer">Supervision Support Department</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Qatar Central Bank, <a href="https://www.qcb.gov.qa/en/pages/the-national-awareness-campaign-for-information-security.aspx" target="_blank" rel="noreferrer">The National Awareness Campaign for Information Security</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:6" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',25)])])}const d=e(r,[["render",s]]);export{p as __pageData,d as default};
